def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    out = [row[:] for row in g]

    def components(cells):
        unseen = set(cells)
        result = []
        while unseen:
            start = unseen.pop()
            comp = {start}
            stack = [start]
            while stack:
                r, c = stack.pop()
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if (nr, nc) in unseen:
                        unseen.remove((nr, nc))
                        comp.add((nr, nc))
                        stack.append((nr, nc))
            result.append(comp)
        return result

    five_cells = {(r, c) for r in range(h) for c in range(w) if g[r][c] == 5}
    color_cells = {(r, c) for r in range(h) for c in range(w)
                   if g[r][c] != 0 and g[r][c] != 5}
    color_comps = components(color_cells)

    for line in components(five_cells):
        rows = [r for r, c in line]
        cols = [c for r, c in line]
        if len(set(rows)) == 1:
            orient = "H"
            fixed = rows[0]
            lo, hi = min(cols), max(cols)
        elif len(set(cols)) == 1:
            orient = "V"
            fixed = cols[0]
            lo, hi = min(rows), max(rows)
        else:
            continue

        for patch in color_comps:
            contacts = []
            for r, c in patch:
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if (nr, nc) in line:
                        contacts.append((nr, nc))
            if not contacts:
                continue

            pr0, pr1 = min(r for r, c in patch), max(r for r, c in patch)
            pc0, pc1 = min(c for r, c in patch), max(c for r, c in patch)

            # Use the line endpoint touched by the adjacent color patch.
            axis_contacts = [c if orient == "H" else r for r, c in contacts]
            endpoint = min(axis_contacts, key=lambda x: min(abs(x-lo), abs(x-hi)))
            if abs(endpoint - lo) <= abs(endpoint - hi):
                endpoint = lo
            else:
                endpoint = hi

            if orient == "H":
                period = pc1 - pc0 + 1
                phase = endpoint - pc0
                for r in range(pr0, pr1 + 1):
                    for c in range(lo, hi + 1):
                        sc = pc0 + ((c - endpoint + phase) % period)
                        out[r][c] = g[r][sc]
            else:
                period = pr1 - pr0 + 1
                phase = endpoint - pr0
                for r in range(lo, hi + 1):
                    sr = pr0 + ((r - endpoint + phase) % period)
                    for c in range(pc0, pc1 + 1):
                        out[r][c] = g[sr][c]

    return out
